// Acessa todos os itens da entrada
const allItems = $input.all();

for (let item of allItems) {
  // Verifica se o item possui dados binários
  if (item.binary && item.binary.data) {
    // Sobrescreve os metadados para "enganar" a API do Groq
    item.binary.data.fileName = 'audio.mp3';
    item.binary.data.mimeType = 'audio/mpeg';
    item.binary.data.fileExtension = 'mp3';
  }
}

return allItems;

